import * as T from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {RoundedBoxGeometry} from './vendor/RoundedBoxGeometry.js';

export function createViewer(container){
 const scene=new T.Scene();scene.background=new T.Color('#f6f7f9');
 const camera=new T.PerspectiveCamera(35,1,.01,50);camera.position.set(1.65,1.25,2.2);
 const renderer=new T.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;container.prepend(renderer.domElement);
 const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,.53,0);controls.enableDamping=true;controls.dampingFactor=.08;controls.minDistance=1.1;controls.maxDistance=5;controls.maxPolarAngle=Math.PI*.88;controls.enablePan=true;
 scene.add(new T.HemisphereLight(0xffffff,0xc9cfdf,2.2));const key=new T.DirectionalLight(0xfff4df,4);key.position.set(-2,4,3);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-2;key.shadow.camera.right=2;key.shadow.camera.top=2;key.shadow.camera.bottom=-2;key.shadow.bias=-.0002;key.shadow.normalBias=.02;scene.add(key);const fill=new T.DirectionalLight(0xe1e9ff,1.5);fill.position.set(2,2,-3);scene.add(fill);
 const floor=new T.Mesh(new T.PlaneGeometry(200,200),new T.ShadowMaterial({color:0x6e788f,opacity:.14}));floor.rotation.x=-Math.PI/2;floor.position.y=-.035;floor.receiveShadow=true;scene.add(floor);
 const chair=new T.Group();scene.add(chair);const parts={};
 const fabric=new T.MeshStandardMaterial({color:0xcfaa43,roughness:.91});const soft=new T.MeshStandardMaterial({color:0xdab74f,roughness:.92});const seam=new T.MeshStandardMaterial({color:0xac8934,roughness:1});const wood=new T.MeshStandardMaterial({color:0x5a4030,roughness:.7});const metal=new T.MeshStandardMaterial({color:0x8994a5,metalness:.72,roughness:.28});const underside=new T.MeshStandardMaterial({color:0x373a3b,roughness:1});
 function mesh(g,m,parent,pos=[0,0,0]){const n=new T.Mesh(g,m.clone());n.castShadow=true;n.receiveShadow=true;n.position.set(...pos);n.userData.original=n.material.color.clone();parent.add(n);return n;}
 function box(parent,size,pos,mat= fabric,r=.04){return mesh(new RoundedBoxGeometry(...size,5,r),mat,parent,pos);}
 function part(id,pos,offset){const g=new T.Group();g.position.set(...pos);g.userData.home=new T.Vector3(...pos);g.userData.offset=new T.Vector3(...offset);chair.add(g);parts[id]=g;return g;}
 const seat=part('seat',[0,.31,.05],[0,.03,.46]);box(seat,[.62,.16,.69],[0,0,0],fabric,.055);box(seat,[.57,.022,.6],[0,-.085,0],underside,.005);
 const cushion=part('cushion',[0,.419,.065],[0,.17,.53]);box(cushion,[.56,.105,.58],[0,0,0],soft,.044);
 const back=part('back',[0,.675,-.29],[0,.38,-.55]);back.rotation.x=-.12;box(back,[.59,.69,.17],[0,0,0],fabric,.08);box(back,[.53,.58,.065],[0,.015,.08],soft,.035);
 for(const x of [-.18,-.06,.06,.18]){const b=mesh(new T.SphereGeometry(.012,14,10),seam,back,[x,-.09,.116]);b.scale.set(1,.7,.35);}
 function piping(parent,points,rad=.0025){const curve=new T.CatmullRomCurve3(points.map(a=>new T.Vector3(...a)));return mesh(new T.TubeGeometry(curve,60,rad,6,false),seam,parent);}
 piping(back,[[-.245,-.26,.105],[-.264,.20,.105],[-.21,.29,.105],[.21,.29,.105],[.264,.20,.105],[.245,-.26,.105]]);
 function side(id,s){const p=part(id,[s*.34,.0,0],[s*.5,.1,.04]);const shape=new T.Shape();shape.moveTo(-.38,.35);shape.lineTo(-.39,.95);shape.quadraticCurveTo(-.30,1.06,-.18,.94);shape.quadraticCurveTo(-.06,.86,-.02,.67);shape.quadraticCurveTo(.02,.59,.14,.61);shape.quadraticCurveTo(.43,.69,.45,.55);shape.quadraticCurveTo(.46,.50,.36,.47);shape.lineTo(.36,.30);shape.quadraticCurveTo(.08,.28,-.38,.35);const geo=new T.ExtrudeGeometry(shape,{steps:1,depth:.075,bevelEnabled:true,bevelSegments:5,bevelSize:.023,bevelThickness:.023,curveSegments:22});geo.rotateY(-Math.PI/2);geo.translate(.0375,0,0);mesh(geo,fabric,p);const arm=box(p,[.115,.09,.36],[0,.6,.24],soft,.043);arm.rotation.x=.15;piping(p,[[s*.055,.34,-.35],[s*.055,.96,-.34],[s*.055,.98,-.23],[s*.055,.83,-.075],[s*.055,.63,.02],[s*.055,.63,.28],[s*.055,.565,.42]],.003);return p;}
 side('left',-1);side('right',1);
 for(const [id,x,z,rear]of [['frontL',-.26,.32,false],['frontR',.26,.32,false],['rearL',-.25,-.27,true],['rearR',.25,-.27,true]]){const leg=part(id,[x,.115,z],[Math.sign(x)*.14,-.09,z>0?.32:-.32]);const n=mesh(new T.CylinderGeometry(.034,.022,.22,24),wood,leg);n.rotation.z=-Math.sign(x)*.04;if(rear)n.rotation.x=-.16;mesh(new T.CylinderGeometry(.011,.011,.055,16),metal,leg,[0,.129,0]);}
 for(const [i,x]of [-.19,.19].entries()){const g=part('stud'+i,[x,.38,-.28],[0,.16,.27]);const m=mesh(new T.CylinderGeometry(.009,.009,.12,12),metal,g);m.rotation.x=Math.PI/2;}
 for(const [i,x]of [-.19,.19].entries()){const g=part('nut'+i,[x,.38,-.21],[0,0,.16]);mesh(new T.CylinderGeometry(.018,.018,.014,6),metal,g).rotation.x=Math.PI/2;mesh(new T.TorusGeometry(.015,.003,8,16),metal,g,[0,0,-.011]);}
 for(const [id,s]of [['left',-1],['right',1]]){let g=part(id+'Bracket',[-s*.048,.77,-.30],[-s*.13,.1,0]);parts[id].add(g);box(g,[.012,.085,.045],[0,0,0],metal,.003);box(g,[.035,.012,.045],[-s*.012,.036,0],metal,.003);box(g,[.012,.033,.045],[-s*.025,.022,0],metal,.003);for(const [i,z]of [-.19,.23].entries()){g=part(id+'Bolt'+i,[s*.285,.285,z],[0,-.16,0]);mesh(new T.CylinderGeometry(.010,.010,.10,14),metal,g);mesh(new T.CylinderGeometry(.019,.019,.016,6),metal,g,[0,-.055,0]);mesh(new T.TorusGeometry(.021,.003,8,16),metal,g,[0,-.044,0]).rotation.x=Math.PI/2;}}
 const caps=part('caps',[0,.216,0],[0,-.11,0]);for(const x of [-.285,.285])for(const z of [-.19,.23])box(caps,[.043,.018,.04],[x,0,z],underside,.004);
 let currentStep=0,progress=0,exploded=false;const assemblyAt={back:0,stud0:1,stud1:1,seat:2,nut0:3,nut1:3,frontL:4,frontR:4,rearL:5,rearR:5,leftBracket:6,rightBracket:6,left:7,leftBolt0:9,leftBolt1:9,right:11,rightBolt0:13,rightBolt1:13,caps:15,cushion:16};
 function reset(){camera.position.set(1.65,1.25,2.2);controls.target.set(0,.53,0);controls.update();}
 function draw(){requestAnimationFrame(draw);for(const [id,g]of Object.entries(parts)){let fraction=1;const at=assemblyAt[id];if(currentStep>0)fraction=currentStep<at?0:currentStep===at?progress:1;let visible=currentStep===0||currentStep>=at-1||at===0;if((id==='left'||id==='right')&&currentStep>=6)visible=true;g.visible=visible;let offset=exploded?1:1-fraction;const target=g.userData.home.clone().addScaledVector(g.userData.offset,offset);if(currentStep===7&&id==='left')target.y+=fraction*.055;if(currentStep===8&&id==='left')target.y+=(1-progress)*.055;if(currentStep===11&&id==='right')target.y+=fraction*.055;if(currentStep===12&&id==='right')target.y+=(1-progress)*.055;g.position.lerp(target,.14);const active=currentStep>0&&(at===currentStep||currentStep===8&&id==='left'||currentStep===12&&id==='right'||currentStep===10&&id.startsWith('leftBolt')||currentStep===14&&id.startsWith('rightBolt'));g.traverse(n=>{if(n.isMesh&&n.parent===g){const hardware=/stud|nut|Bolt|Bracket|caps/i.test(id);n.material.color.copy(active&&hardware?new T.Color(0x3a6aff):n.userData.original);n.material.emissive?.setHex(active?0x16316c:0);n.material.emissiveIntensity=active?.24:0;}});const rotate=active&&/front|rear|stud|nut|Bolt/.test(id);if(id!=='back'){g.rotation.y=rotate&&!/stud|nut/.test(id)?(1-progress)*Math.PI*4:0;g.rotation.z=rotate&&/stud|nut/.test(id)?(1-progress)*Math.PI*4:0;}}
 controls.update();renderer.render(scene,camera);}
 new ResizeObserver(()=>{const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}).observe(container);draw();
 return{setState(step,p){currentStep=step;progress=p;},setExploded(v){exploded=v;},reset,underside(){camera.position.set(1.3,-.75,1.55);controls.target.set(0,.34,0);controls.update();}};
}
